		{x=800,y=220,w=233,avail=43,size=40,fg={90,60,33},bg={255,253,236},cover={{800,220,1033,259}},ko="총 획득 경험치"},
		{x=800,y=261,w=538,avail=36,size=17,fg={90,60,33},bg={255,253,236},cover={{800,261,1338,276},{800,279,1159,296}},ko="캐릭터를 변경해도 같은 양의 경험치를 자동으로 받아 동일한 레벨로 돌아갑니다."},
		{x=800,y=310,w=90,avail=17,size=14,fg={90,60,33},bg={255,253,236},cover={{800,310,890,323}},ko="능력치 상세"},
		{x=800,y=316,w=537,avail=70,size=18,fg={90,60,33},bg={255,253,236},cover={{800,316,1296,350},{800,350,1337,366},{800,368,1152,385}},ko="여기서 능력치를 볼 수 있습니다. 표시되는 수치는 최종값으로, 버프의 공격력, 지형의 이동 속도, 방어구의 방어력 등 외부 보정이 이미 반영되어 있습니다."},
		{x=800,y=400,w=184,avail=20,size=17,fg={90,60,33},bg={255,253,236},cover={{800,400,984,416}},ko="능력치 포인트 사용 버튼"},
		{x=800,y=412,w=470,avail=28,size=18,fg={90,60,33},bg={255,253,236},cover={{800,412,1270,436}},ko="능력치 포인트가 있으면 버튼이 표시됩니다."},
		{x=800,y=441,w=514,avail=76,size=17,fg={90,60,33},bg={255,253,236},cover={{800,441,1271,457},{800,459,1314,475},{800,480,1297,495},{800,499,1204,516}},ko="누르면 포인트를 사용해 해당 능력치가 상승합니다. 상승량은 모드 설정에서 조절할 수 있습니다. 획득 속도를 높이는 x10, MAX 버튼도 있습니다. MAX 버튼은 남은 포인트를 모두 사용하니 주의하십시오."},
		{x=800,y=530,w=515,avail=43,size=18,fg={90,60,33},bg={255,253,236},cover={{800,530,1315,569}},ko="속성 상세 (비용/획득 횟수)"},
		{x=800,y=570,w=515,avail=38,size=14,fg={90,60,33},bg={255,253,236},cover={{800,570,1315,585},{800,589,906,601}},ko="처음에는 1 포인트가 들지만, 해당 능력치를 많이 획득할수록 비용이 비싸집니다."},
		{x=800,y=620,w=518,avail=95,size=17,fg={90,60,33},bg={255,253,236},cover={{800,620,892,632},{800,639,1318,655},{800,658,1302,676},{800,678,1053,695},{800,699,1146,714}},ko="초기화 버튼. 누르면 사용한 능력치 포인트가 모두 초기화되고 일부(85%)를 돌려받습니다. 최대 체력 페널티도 함께 적용되며, 두 값 모두 모드 설정에서 조절할 수 있습니다. 레벨이나 경험치는 초기화되지 않습니다."},
		{x=800,y=729,w=510,avail=80,size=16,fg={90,60,33},bg={255,253,236},cover={{800,729,917,741},{800,747,1310,764},{800,767,865,782},{800,788,1183,803}},ko="펫 레벨 버튼. 누르면 펫 레벨 창으로 전환됩니다. (자세한 내용은 능력 항목 참고) \"펫 미포함\" 특전이 있어야만 표시됩니다."},
	},
	["basic_guide_4"] = {
		{x=95,y=60,w=64,avail=41,size=38,fg={49,60,115},bg={255,253,236},cover={{95,60,159,97}},ko="팁 :"},
		{x=148,y=117,w=513,avail=38,size=17,fg={90,60,33},bg={255,253,236},cover={{148,117,655,133},{148,136,661,152}},ko="레벨 업 할 때마다 경험치가 초기화됩니다. 다음 목표치도 함께 올라가므로 레벨이 높을수록 레벨 업이 더 어려워집니다."},
		{x=141,y=186,w=527,avail=27,size=18,fg={90,60,33},bg={255,253,236},cover={{141,186,668,209}},ko="현재 경험치는 작업(벌목, 채굴, 땅 파기 등),"},
		{x=148,y=207,w=556,avail=105,size=17,fg={90,60,33},bg={255,253,236},cover={{148,207,671,225},{148,229,703,245},{148,256,698,272},{148,276,704,292},{148,295,650,312}},ko="몹 처치, 작물 심기와 돌보기, 요리(냄비 사용), 식사, 낚시, 제작, 채집으로 얻을 수 있습니다. 일부 캐릭터는 특히 잘하는 작업을 할 때 다른 캐릭터보다 더 많은 경험치를 얻습니다. 우디와 맥스웰은 작업, 위그프리드는 몹 처치, 웜우드는 작물 심기, 왈리는 요리와 식사,"},
		{x=148,y=314,w=558,avail=31,size=18,fg={90,60,33},bg={255,253,236},cover={{148,314,706,341}},ko="워트는 낚시, 위노나는 제작이 해당됩니다."},
		{x=148,y=334,w=246,avail=20,size=17,fg={90,60,33},bg={255,253,236},cover={{148,334,394,350}},ko="보너스가 커서 잘 활용해야 합니다."},
		{x=124,y=375,w=466,avail=26,size=18,fg={90,60,33},bg={255,253,236},cover={{124,375,590,397}},ko="웨스는 무엇을 하든 경험치를 25% 더 얻어"},
		{x=148,y=391,w=549,avail=36,size=18,fg={90,60,33},bg={255,253,236},cover={{148,391,697,423}},ko="자신의 쓸모없음을 보완합니다."},
		{x=144,y=445,w=530,avail=80,size=17,fg={90,60,33},bg={255,253,236},cover={{148,445,666,461},{148,465,674,482},{144,486,636,502},{148,505,254,521}},ko="몹을 처치할 때 혼자 잡으면 더 많은 경험치를 얻습니다. 그렇지 않으면 경험치가 피해를 주지 않은 근처 플레이어에게도 균등하게 나뉘기 때문입니다. 이를 어시스트 경험치라고 하며, 어시스트 범위는 모드 설정에서 조절할 수 있습니다."},
		{x=148,y=541,w=521,avail=80,size=18,fg={90,60,33},bg={255,253,236},cover={{148,541,669,558},{148,561,649,578},{148,581,654,598},{148,601,324,616}},ko="더 강한 몹을 처치하거나 더 좋은 음식을 먹으면 경험치를 더 얻습니다. 마찬가지로 건축물 제작이 아이템 제작보다, 바다 물고기 낚시가 연못 물고기보다, 특정 씨앗 심기가 일반 씨앗보다 더 많은 경험치를 줍니다."},
		{x=148,y=637,w=513,avail=76,size=18,fg={90,60,33},bg={255,253,236},cover={{148,637,661,654},{148,656,620,674},{148,677,620,694},{148,695,417,713}},ko="참고로 추종자가 처치하거나 작업한 것은 경험치를 주지 않으므로(편법 방지), 직접 마지막 일격을 가해야 진행됩니다. 단 어인 워든, \"버니\", \"맥스웰 그림자 하수인\", 복슬이, \"아비게일\"은 예외입니다."},
		{x=148,y=734,w=557,avail=40,size=18,fg={90,60,33},bg={255,253,236},cover={{148,734,705,758},{148,754,704,781}},ko="능력치 세부 정보 항목의 능력치는 총합입니다. 방어구, 버프, 밟고 있는 토탄의 보너스도 포함됩니다."},
		{x=830,y=60,w=516,avail=163,size=18,fg={90,60,33},bg={255,253,236},cover={{830,60,1317,76},{830,80,1335,97},{830,100,1296,117},{830,117,1346,135},{830,139,1304,155},{830,160,1312,176},{830,179,1338,196},{830,200,1050,216}},ko="기본적으로 능력치 포인트를 초기화해도 포인트가 100% 반환되지는 않습니다. 하지만 \"월석 우상\"으로 캐릭터를 바꾸면 능력치 포인트를 유지한 채 포인트를 모두 돌려받습니다. 게임 초반 몇 년간은 유용한 능력치가 따로 있고 후반에는 공격력에 집중하는 편이 훨씬 좋으므로 매우 유용합니다. 이렇게 하면 우디나 맥스웰 같은 자원 채집이나 작업 위주 캐릭터를 먼저 고르고, 나중에 위그프리드나 윌로우 같은 전투형 캐릭터로 진행 상황을 잃지 않고 바꿀 수 있습니다."},
	},
