	["perk_expert_30"] = {
		{x=95,y=59,w=64,avail=41,size=38,fg={90,56,82},bg={255,253,236},cover={{95,59,159,96}},ko="팁 :"},
		{x=149,y=109,w=517,avail=119,size=19,fg={90,60,33},bg={255,253,236},cover={{149,109,656,146},{149,137,643,171},{149,168,660,185},{149,188,666,205},{149,208,423,224}},ko="볼프강은 거미나 사냥개 같은 몹 무리에 강합니다. \"글래디에이터 가레아\"는 빠르게 레벨업하고 \"아레스의 흉갑\"은 받는 피해를 모두 반사합니다. 다만 보스에게는 효과가 덜합니다. 보스는 공격이 빠르지 않아 \"글래디에이터 가레아\"를 효율적으로 레벨업하기 어렵고, 체력이 높아 \"아레스의 흉갑\"의 반사 피해로도 큰 차이를 내지 못하기 때문입니다."},
		{x=149,y=224,w=556,avail=89,size=19,fg={90,60,33},bg={255,253,236},cover={{149,224,703,253},{149,257,652,274},{149,269,705,309}},ko="다른 캐릭터와 달리 볼프강은 공격력, 이동 속도, 방어력 능력치보다 체력에 투자하는 편이 낫습니다. 그러면 \"아레스의 흉갑\"의 최대 체력이 늘고 \"글래디에이터 가레아\"의 반사 피해도 커집니다."},
		{x=149,y=338,w=498,avail=40,size=19,fg={90,60,33},bg={255,253,236},cover={{149,338,647,359},{149,358,513,384}},ko="메멘토의축복 특전을 찍으면 \"수정 구슬\"이 볼프강의 반사 피해를 더 늘려 주어 매우 유용합니다."},
		{x=149,y=399,w=508,avail=79,size=19,fg={90,60,33},bg={255,253,236},cover={{149,399,654,416},{149,420,618,440},{149,436,657,456},{149,458,230,474}},ko="피해를 받아내며 팀을 보호하는 탱크 역할을 좋아한다면 볼프강을 고르십시오. 많은 피해를 견디면서 공격력도 준수합니다. 다수의 적을 상대하는 데 매우 뛰어나지만 보스전에서는 약합니다."},
		{x=991,y=69,w=127,avail=41,size=38,fg={90,56,82},bg={255,253,236},cover={{991,69,1118,106}},ko="위노나"},
		{x=761,y=590,w=582,avail=40,size=16,fg={90,60,33},bg={255,253,236},cover={{762,590,1343,605},{761,610,1343,626}},ko="위노나의 특전은 그녀를 최고 수준의 건축가로 만들어, 기지를 세울 때는 위노나로 교체하는 것이 필수적입니다. 기지가 완성되면 자신의 플레이 스타일에 더 맞는 캐릭터로"},
