	["rog_15"] = {
		{x=382,y=401,w=41,avail=17,size=14,fg={90,60,33},bg={255,253,236},cover={{382,401,423,414}},ko="10000"},
		{x=78,y=435,w=578,avail=200,size=16,fg={90,60,33},bg={255,253,236},cover={{78,435,600,452},{78,455,331,471},{78,474,649,491},{78,495,118,511},{78,514,482,531},{78,534,216,547},{78,553,656,569},{78,573,289,590},{78,593,443,609},{78,614,128,626}},ko="- 플레이어가 \"대게왕\" 근처에서 \"바람 소라\"를 연주해 \"게 여왕\"으로 변신시켜야만 등장합니다. - 변신 후 여왕에게 보석을 끼우면 \"대게왕\"과 마찬가지로 전투가 시작됩니다. - 대게왕과 달리 끼운 보석은 여왕의 능력치를 올려주지 않습니다. - 불에 타지 않습니다. - 능력 : \"원소 게 집게\"를 최대 6마리 소환합니다. 하나라도 살아 있으면 타격당 최대 1의 피해만 받습니다. - 능력 : \"원소 게 집게\"의 주문 중 하나를 시전합니다. - 전리품 :"},
		{x=307,y=698,w=142,avail=21,size=18,fg={165,150,41},bg={255,253,236},cover={{307,698,449,715}},ko="1-2 젤리빈 (각각)"},
		{x=283,y=790,w=190,avail=21,size=16,fg={165,150,41},bg={255,253,236},cover={{283,790,473,807}},ko="1-3 원소 기관 (각각)"},
		{x=871,y=69,w=367,avail=41,size=38,fg={90,56,82},bg={255,253,236},cover={{871,69,1238,106}},ko="원소 게 집게"},
		{x=773,y=120,w=562,avail=17,size=14,fg={90,60,33},bg={255,253,236},cover={{773,120,1335,133}},ko="전기 집게  물의 집게  얼음 집게  불의 집게  그림자 집게  달의 집게"},
		{x=754,y=271,w=596,avail=140,size=16,fg={90,60,33},bg={255,253,236},cover={{755,271,1350,287},{755,292,1328,308},{755,310,1295,328},{754,330,1334,347},{755,352,1036,367},{755,371,1177,387},{755,391,804,403}},ko="- \"게 여왕\"이 소환합니다. 소환되는 원소 집게의 종류는 여왕에게 끼운 보석에 따라 달라집니다. 보석마다 대응하는 집게의 소환 확률이 올라갑니다: 노란색(전기), 주황색(물), 파란색(얼음), 녹색(달), 보라색(그림자), 빨간색(불). 보석을 끼우지 않아도 해당 집게가 나올 수 있지만 확률은 훨씬 낮습니다. - 원거리 투사체로 공격하지만 공격 속도는 느립니다. - 전리품 :"},
		{x=898,y=486,w=296,avail=21,size=16,fg={165,150,41},bg={255,253,236},cover={{898,486,1194,503}},ko="전기 기관  물 기관  얼음 기관"},
		{x=911,y=572,w=293,avail=21,size=16,fg={165,150,41},bg={255,253,236},cover={{911,572,1204,589}},ko="불 기관  그림자 기관  달 기관"},
		{x=852,y=594,w=405,avail=21,size=16,fg={90,60,33},bg={255,253,236},cover={{852,594,1257,611}},ko="각 집게의 원소에 맞는 원소 기관 (10%)"},
	},
	["rog_16"] = {
		{x=226,y=61,w=93,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{226,61,319,73}},ko="전기 집게"},
		{x=271,y=93,w=169,avail=33,size=30,fg={90,60,33},bg={255,253,236},cover={{271,93,440,122}},ko="200 원거리 17"},
		{x=226,y=129,w=477,avail=133,size=17,fg={90,60,33},bg={255,253,236},cover={{226,129,639,145},{226,148,364,161},{226,169,424,185},{226,188,396,204},{226,208,628,223},{226,224,702,245},{226,236,703,264}},ko="- 공격 투사체가 근처의 다른 대상에게 튕깁니다. - 불에 탈 수 없습니다. - 평면 대미지 면역. - 전기 피해를 입힙니다. - 젖었거나 공격자가 젖은 상태에서만 공격할 수 있습니다. - 주문 : 근처 플레이어에게 전기 표식을 남깁니다. 잠시 후 표식 대상에서 멀리 떨어진 모든 플레이어와 근처의 \"물의 집게\"에 번개가 떨어집니다."},
		{x=234,y=267,w=472,avail=80,size=18,fg={90,60,33},bg={255,253,236},cover={{236,267,704,314},{234,308,654,323},{256,315,706,343}},ko="젖기만 하면 \"전기 집게\"를 공격할 수 있어 가장 상대하기 쉽고, 주문도 해를 주지 않아 솔로 플레이에 유리합니다."},
		{x=226,y=358,w=80,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{226,358,306,370}},ko="물의 집게"},
		{x=277,y=391,w=167,avail=20,size=17,fg={90,60,33},bg={255,253,236},cover={{277,391,444,407}},ko="200 원거리 85"},
		{x=226,y=425,w=441,avail=160,size=17,fg={90,60,33},bg={255,253,236},cover={{226,425,423,442},{226,445,364,458},{226,466,424,482},{226,484,551,500},{226,504,667,520},{226,525,625,540},{226,545,661,560},{226,564,514,580}},ko="- 공격 시 대상을 젖게 합니다. - 불에 탈 수 없습니다. - 평면 대미지 면역. - 전기 공격으로만 공격할 수 있습니다. - 주문 : 근처 플레이어에게 물 표식을 남깁니다. 잠시 후 대상 위치에 물보라를 일으켜 맞은 모든 플레이어의 장비가 공중으로 튕겨 나갑니다. 물보라는 근처의 \"전기 집게\"도 즉시 죽입니다."},
		{x=249,y=585,w=397,avail=30,size=18,fg={90,60,33},bg={255,253,236},cover={{249,585,646,611}},ko="\"물의 집게\" 주문의 물보라는"},
		{x=233,y=604,w=413,avail=40,size=17,fg={90,60,33},bg={255,253,236},cover={{233,604,646,621},{256,624,487,640}},ko="착용 중인 장비만 떨어뜨리므로 미리 모두 해제해 두면 효과를 완전히 막을 수 있습니다."},
		{x=903,y=61,w=59,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{903,61,962,73}},ko="얼음 집게"},
