		{x=840,y=69,w=430,avail=41,size=38,fg={90,56,82},bg={255,253,236},cover={{840,69,1270,106}},ko="캐릭터 전용 아이템"},
		{x=991,y=115,w=127,avail=20,size=17,fg={165,150,41},bg={255,253,236},cover={{991,115,1118,131}},ko="프리즘 전초기지"},
		{x=791,y=347,w=543,avail=66,size=18,fg={90,60,33},bg={255,253,236},cover={{799,347,1267,377},{791,380,1334,406}},ko="(빈 \"프리즘 전초기지\") (\"프리즘 전초기지\" 중첩 버프 보유)"},
		{x=1032,y=424,w=81,avail=34,size=31,fg={90,60,33},bg={255,253,236},cover={{1032,424,1113,454}},ko="구조물"},
		{x=755,y=457,w=595,avail=189,size=15,fg={90,60,33},bg={255,253,236},cover={{755,457,1345,473},{755,477,1020,493},{755,497,1350,513},{755,516,1290,532},{756,537,1329,552},{778,559,1331,581},{774,572,1331,597},{786,602,831,617}},ko="- \"월석 우상\"을 바치면 \"천상의 포털\"처럼 플레이어를 캐릭터 선택 화면으로 되돌립니다. - \"무지개 보석\"을 바칠 때 플레이어가 달수정을 먹는자 특전을 가지고 있으면 모든 달수정을 먹는자 중첩 버프를 제거해 \"프리즘 전초기지\"에 저장합니다. 이미 달수정을 먹는자 중첩 버프가 저장되어 있으면 대신 플레이어에게 부여합니다. \"프리즘 전초기지\"는 주로 달수정을 먹는자 중첩 버프를 잃지 않고 캐릭터를 바꾸거나 버프를 다른 플레이어에게 넘기려는 경우에 사용합니다."},
		{x=778,y=634,w=517,avail=22,size=18,fg={90,60,33},bg={255,253,236},cover={{778,634,1295,652}},ko="살펴보면 저장된 달수정 중첩 버프 수를 확인할 수 있습니다."},
	},
	["rog_28"] = {
		{x=339,y=61,w=76,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{339,61,415,73}},ko="띵커벨"},
		{x=282,y=187,w=242,avail=52,size=49,fg={90,60,33},bg={255,253,236},cover={{282,187,524,235}},ko="손 슬롯 34 666"},
		{x=78,y=236,w=628,avail=110,size=16,fg={90,60,33},bg={255,253,236},cover={{78,236,703,259},{78,259,614,275},{78,269,704,314},{78,315,706,342}},ko="- 인벤토리에 있을 때 공격으로 10을 넘는 피해를 받으면 작은 토네이도가 공격자에게 달라붙어 주기적 피해를 주고 닿는 것을 모두 파괴하며 1초 후 사라집니다. - 착용 중 공격을 회피해도 같은 토네이도가 달라붙습니다."},
		{x=78,y=338,w=586,avail=114,size=16,fg={90,60,33},bg={255,253,236},cover={{78,338,323,353},{78,357,664,373},{78,378,657,393},{79,396,637,413},{102,420,659,439},{89,433,402,458}},ko="1초 후 사라집니다. - 덤벨로 들어 올릴 때: 정신력이 10 증가하지만 강함(Mightiness)이 10 감소합니다. - 던졌을 때: 착지 지점에 토네이도를 최대 5개 소환합니다. 토네이도는 30초 동안 몰아치며 주기적으로 피해를 주고 닿는 모든 것을 파괴합니다. \"윈덤벨(Windumbell)\"을 인벤토리에 여러 개 소지하면 효과가 중첩되어 피격 시 더 많은 토네이도가 생성됩니다."},
		{x=339,y=467,w=76,avail=17,size=14,fg={165,150,41},bg={255,253,236},cover={{339,467,415,480}},ko="비단 볼라"},
		{x=311,y=621,w=183,avail=32,size=29,fg={90,60,33},bg={255,253,236},cover={{311,621,494,649}},ko="손 슬롯 무한"},
		{x=78,y=670,w=624,avail=60,size=16,fg={90,60,33},bg={255,253,236},cover={{78,670,645,687},{78,690,600,706},{78,710,702,733}},ko="- 지정한 위치에 던져 그곳의 작은 거미를 모두 포획합니다. 거미가 없거나 \"비단 볼라\"가 가득 찬 상태라면 저장된 거미를 모두 풀어놓습니다. - 최대 16마리까지 저장할 수 있습니다."},
		{x=1025,y=60,w=60,avail=17,size=14,fg={165,150,41},bg={255,253,236},cover={{1025,60,1085,73}},ko="유령지팡이"},
		{x=765,y=205,w=514,avail=44,size=16,fg={90,60,33},bg={255,253,236},cover={{765,205,1279,245}},ko="손 슬롯 51 무한 우클릭 주문"},
		{x=755,y=252,w=582,avail=140,size=16,fg={90,60,33},bg={255,253,236},cover={{755,252,1337,269},{756,273,804,285},{755,292,1306,309},{756,313,880,325},{755,331,956,348},{756,352,1308,367},{765,368,1093,387}},ko="- 착용 시 아비게일이 사용자의 공격력, 이동 속도, 방어력 능력치 레벨을 그대로 물려받습니다. - 재사용 대기 중이 아닐 때 \"유령지팡이\"에 빙의하면 부활합니다. 이 경우 4분의 재사용 대기가 적용됩니다. - 주문(영역 우클릭) : - 지정한 지역에 있는 모든 플레이어 유령을 부활시킵니다. 근처에 플레이어 유령이 없으면 대신 \"꼬마 유령\"을 소환합니다."},
		{x=815,y=392,w=169,avail=16,size=13,fg={90,60,33},bg={255,253,236},cover={{815,392,984,404}},ko="- 재사용 대기시간: 2분."},
		{x=1003,y=417,w=104,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{1003,417,1107,429}},ko="전기 히터"},
		{x=807,y=602,w=450,avail=24,size=16,fg={90,60,33},bg={255,253,236},cover={{807,602,1257,622}},ko="(\"전기 히터\" 재사용 대기)  (\"전기 히터\" 준비)"},
		{x=1046,y=640,w=67,avail=16,size=13,fg={90,60,33},bg={255,253,236},cover={{1046,640,1113,652}},ko="구조물"},
		{x=755,y=673,w=586,avail=140,size=16,fg={90,60,33},bg={255,253,236},cover={{755,673,1105,686},{755,694,939,706},{755,714,1341,730},{756,734,980,749},{755,753,1292,769},{755,772,1331,787},{756,793,896,805}},ko="- 재사용 대기 중이 아닐 때 켜고 끌 수 있습니다. - 작동 중에는 열을 방출합니다. - 작동 중에는 근처의 불씨가 10개를 넘지 않는 한 10초마다 \"천상의 불씨\"를 1개씩 생성합니다. - 작동 중에는 부패하는 식용 아이템을 무엇이든 넣어 신선도를 완전히 회복시킬 수 있습니다. 아이템 1중첩마다 5초의 재사용 대기가 발생하며, 중첩되지 않는 아이템은 50초가 걸립니다."},
	},
