		{x=78,y=224,w=625,avail=24,size=18,fg={90,60,33},bg={255,253,236},cover={{78,224,702,245},{79,236,703,260}},ko="- \"풍선더미\"의 상위 버전으로, 개량되고 강화된 풍선을 제작하는 데 쓰입니다."},
		{x=78,y=269,w=627,avail=44,size=18,fg={90,60,33},bg={255,253,236},cover={{78,269,705,309}},ko="제작 가능한 신규 풍선 :"},
		{x=199,y=315,w=507,avail=31,size=18,fg={90,60,33},bg={255,253,236},cover={{199,315,706,342}},ko="- 터지면 50:50 확률로 행운/불운 판정을 합니다"},
