		{x=208,y=513,w=454,avail=96,size=13,fg={90,60,33},bg={255,253,236},cover={{208,513,345,529},{208,534,645,550},{209,553,511,569},{208,573,662,589},{209,596,275,605}},ko="초록 점액 풍선 - 행운 : 모든 플레이어가 체력, 정신력, 허기를 25 얻고 인벤토리의 모든 아이템이 완전히 회복됩니다. - 불운 : 모든 플레이어 근처에 포자 구름을 생성해 점액에 가둡니다."},
		{x=208,y=667,w=418,avail=42,size=17,fg={90,60,33},bg={255,253,236},cover={{209,667,353,683},{208,688,626,704}},ko="마법 잎사귀 풍선 - 행운 : 넓은 범위의 모든 나무를 베고 그루터기를 캡니다."},
		{x=208,y=707,w=492,avail=39,size=18,fg={90,60,33},bg={255,253,236},cover={{208,707,700,733},{208,730,236,742}},ko="- 불운 : 주변 나무가 \"나무괴물\"로 변해 공격합니다."},
		{x=885,y=94,w=436,avail=57,size=17,fg={90,60,33},bg={255,253,236},cover={{886,94,990,110},{885,113,1162,128},{885,132,1321,149}},ko="굴착 풍선 - 행운 : 넓은 범위의 모든 바위를 캡니다. - 불운 : 모든 플레이어를 노리는 운석 비를 내립니다."},
		{x=885,y=191,w=355,avail=40,size=17,fg={90,60,33},bg={255,253,236},cover={{886,191,1000,207},{885,211,1240,227}},ko="노른자 풍선 - 행운 : 좁은 범위의 모든 알을 즉시 부화시킵니다."},
		{x=896,y=230,w=423,avail=21,size=18,fg={90,60,33},bg={255,253,236},cover={{896,230,1319,247}},ko="- 불운 : 모든 플레이어 근처에 성난 키다리새 무리를 생성합니다."},
		{x=893,y=248,w=428,avail=103,size=18,fg={90,60,33},bg={255,253,236},cover={{909,248,1321,267},{893,270,1319,287},{915,291,948,303},{909,308,1271,327},{896,318,1268,347}},ko="알이 이미 부화 중이어야 합니다. 먼저 알맞은 환경에 몇 초 동안 내려놓으십시오. 알 부화 시간을 건너뛸 수 있어 업적이나 \"냉각된 용암벌레\"를 빠르게 얻을 때 유용합니다."},
		{x=1025,y=361,w=59,avail=16,size=13,fg={165,150,41},bg={255,253,236},cover={{1025,361,1084,373}},ko="도끼/도끼"},
		{x=903,y=581,w=354,avail=35,size=18,fg={90,60,33},bg={255,253,236},cover={{903,581,1257,612}},ko="손 슬롯 66.6 666 ROW"},
		{x=755,y=633,w=593,avail=160,size=17,fg={90,60,33},bg={255,253,236},cover={{755,633,1284,649},{755,652,1320,669},{755,672,1093,688},{755,693,1316,709},{756,712,915,727},{755,731,1348,748},{756,751,1334,767},{756,771,956,787}},ko="- 이것으로 나무를 베면 주변의 동일한 벌목 대상도 함께 베입니다. - 인벤토리에 있으면 \"웨어구스(Weregoose)\"가 광전사의 외침(Berserker Call) 능력을 얻습니다 : 12초마다 주변 몹을 도발해 자신을 노리게 합니다. - 인벤토리에 있으면 \"웨어비버(Werebeaver)\"가 줍기(Pick Up) 능력을 얻습니다 : 주변의 주울 수 있는 아이템을 자동으로 줍습니다. - 인벤토리에 있으면 \"웨어무스(Weremoose)\"가 도살의 칼날(Culling Blade) 능력을 얻습니다 : 현재 체력이 0.5% 미만인 보스를 공격하면 즉시 처치합니다. 이때 방어력 능력치 레벨이 1 증가합니다."},
	},
	["rog_31"] = {
		{x=338,y=60,w=78,avail=17,size=14,fg={165,150,41},bg={255,253,236},cover={{338,60,416,73}},ko="태양광 패널"},
		{x=369,y=269,w=336,avail=44,size=41,fg={90,60,33},bg={255,253,236},cover={{369,269,705,309}},ko="구조물"},
		{x=78,y=313,w=624,avail=179,size=18,fg={90,60,33},bg={255,253,236},cover={{78,313,702,349},{78,352,140,365},{78,371,666,387},{79,391,609,408},{78,411,466,428},{78,431,633,448},{78,451,672,467},{79,471,148,486}},ko="- 겨울을 제외한 낮 동안 자동으로 켜져 햇빛을 흡수해 에너지를 얻습니다. 5초마다 에너지 1, 여름에는 5초마다 3을 얻습니다. - 에너지가 있으면 충전량이 있는 아이템을 건네 충전할 수 있습니다. 아이템의 충전량이 가득 차 있지 않으면 태양광 패널이 모든 에너지를 아이템으로 옮겨 에너지 비율을 충전량 비율로 바꿉니다. - 에너지가 10%를 넘으면 \"톱니바퀴\"를 건네 \"충전된 톱니바퀴\"를, \"달 유리\"를 건네 \"충전된 달 파편\"을 만들 수 있습니다. 중첩 1개당 에너지 10%를 소모합니다."},
		{x=101,y=494,w=556,avail=62,size=18,fg={90,60,33},bg={255,253,236},cover={{101,494,657,522},{101,516,657,532},{108,536,140,549}},ko="충전량 보유 아이템 : \"글래디에이터 가레아\", \"프라이팬\", \"썬더볼트\", \"메테오 스태프\", \"광합성 지팡이\", \"신비한 물\", \"감전 다트\", \"스파크안경 200\""},
		{x=101,y=570,w=346,avail=21,size=18,fg={90,60,33},bg={255,253,236},cover={{101,570,447,587}},ko="살펴보면 저장된 에너지 양을 알 수 있습니다."},
		{x=238,y=608,w=463,avail=138,size=17,fg={90,60,33},bg={255,253,236},cover={{238,608,341,624},{238,628,499,641},{238,647,651,664},{238,668,370,684},{238,687,645,703},{238,708,701,733},{238,726,660,742}},ko="충전된 톱니바퀴 - \"톱니바퀴\"와 음식 능력치가 같습니다. - WX-78이 먹으면 회로 충전량이 6 증가합니다. - 희미한 빛을 냅니다. - \"톱니바퀴\"처럼 구조물을 수리할 수 있으며 수리량은 10 배입니다. - 15일이 지나면 부패해 \"톱니바퀴\"로 되돌아갑니다."},
		{x=101,y=760,w=603,avail=27,size=18,fg={90,60,33},bg={255,253,236},cover={{101,760,704,783}},ko="내뿜는 희미한 빛이 비상시에 요긴하게 쓰입니다."},
		{x=997,y=60,w=114,avail=20,size=17,fg={165,150,41},bg={255,253,236},cover={{997,60,1111,76}},ko="스파크안경 200"},
		{x=997,y=248,w=300,avail=25,size=18,fg={90,60,33},bg={255,253,236},cover={{997,248,1297,269}},ko="17+ 무한 충전량 보유"},
		{x=755,y=282,w=592,avail=160,size=17,fg={90,60,33},bg={255,253,236},cover={{755,282,913,298},{755,302,1347,319},{756,323,1326,338},{755,341,1269,358},{755,361,1296,378},{755,381,1078,397},{755,402,1147,418},{755,421,1159,437}},ko="- 충전량 0으로 시작합니다. - 활성 회로에 따라 공격력이 증가합니다: \"전기화 회로\" 1개당 +10, \"열 회로\" 1개당 +7, \"발광 회로\" 1개당 +5. 또한 WX-78의 현재 회로 충전량 1당 공격력이 +3 증가합니다. - 공격할 때마다 충전량이 2.5% 감소합니다. 충전량이 0이면 공격할 때마다 대신 WX-78의 회로 충전량을 1 소모합니다. - 장착 시 WX-78의 회로 충전량이 3 감소합니다. - 장착 중 공격받으면 \"스파크안경 200\"을 떨어뜨립니다."},
		{x=998,y=447,w=114,avail=20,size=17,fg={165,150,41},bg={255,253,236},cover={{998,447,1112,463}},ko="돋보기 안경"},
		{x=1005,y=547,w=150,avail=52,size=49,fg={90,60,33},bg={255,253,236},cover={{1005,547,1155,595}},ko="머리 슬롯 30"},
		{x=755,y=598,w=560,avail=40,size=17,fg={90,60,33},bg={255,253,236},cover={{755,598,1315,614},{756,618,1291,634}},ko="- 착용 시 마법책을 읽을 수 있습니다. 이미 읽을 수 있다면 읽기 속도가 2배가 됩니다. 책을 읽을 때마다 내구도가 감소합니다."},
		{x=1009,y=644,w=91,avail=19,size=16,fg={165,150,41},bg={255,253,236},cover={{1009,644,1100,659}},ko="공훈 배지"},
		{x=755,y=737,w=581,avail=40,size=17,fg={90,60,33},bg={255,253,236},cover={{755,737,1336,754},{755,757,922,773}},ko="- 이동식 보관함 안에 있으면 주변 모든 플레이어에게 공격력 25% 증가 버프를 부여합니다."},
		{x=776,y=785,w=472,avail=29,size=18,fg={90,60,33},bg={255,253,236},cover={{776,785,1248,810}},ko="\"워비\", \"체스터\", \"허치\"가 그 예입니다."},
	},
	["rog_32"] = {
		{x=326,y=61,w=104,avail=19,size=16,fg={165,150,41},bg={255,253,236},cover={{326,61,430,76}},ko="배달 전화기"},
		{x=369,y=269,w=335,avail=46,size=43,fg={74,74,74},bg={255,253,236},cover={{369,269,704,311}},ko="건축물"},
		{x=78,y=315,w=624,avail=38,size=17,fg={90,60,33},bg={255,253,236},cover={{78,315,702,349}},ko="- 배달 전화기는 3~5일마다 울립니다."},
		{x=78,y=353,w=586,avail=95,size=17,fg={90,60,33},bg={255,253,236},cover={{79,353,636,369},{78,373,645,389},{78,392,654,407},{78,411,664,428},{79,430,540,448}},ko="울릴 때 주우면 미니게임이 시작되어 무작위 손님이 나타나 특정 요리를 요청합니다. 요청받은 요리를 배달하면 미니게임이 완료되고 무작위 전리품과 경험치를 얻습니다. 어려운 요리일수록 보상이 좋고, 배달이 빠를수록 더 많은 전리품과 경험치를 줍니다. 충분히 빨리 배달하면 보너스 별도 얻을 수 있습니다. (왈리가 배달하면 항상 보너스 별을 받습니다)."},
		{x=340,y=456,w=75,avail=17,size=14,fg={165,150,41},bg={255,253,236},cover={{340,456,415,469}},ko="손님"},
		{x=78,y=620,w=341,avail=42,size=17,fg={90,60,33},bg={255,253,236},cover={{78,620,297,636},{78,641,419,657}},ko="- \"배달 전화기\"에서 생성됩니다. - 원하는 요리를 주면 경험치와 전리품을 줍니다."},
		{x=101,y=674,w=331,avail=21,size=17,fg={90,60,33},bg={255,253,236},cover={{101,674,432,691}},ko="조사하면 원하는 요리를 알 수 있습니다."},
		{x=973,y=60,w=163,avail=20,size=17,fg={165,150,41},bg={255,253,236},cover={{973,60,1136,76}},ko="카엘 신성한 성경"},
		{x=740,y=223,w=587,avail=52,size=17,fg={90,60,33},bg={255,253,236},cover={{740,223,1327,271}},ko="손 슬롯 17+ 4 우클릭 주문"},
		{x=755,y=275,w=593,avail=340,size=17,fg={90,60,33},bg={255,253,236},cover={{755,275,1163,290},{755,294,1239,311},{755,314,1324,330},{755,334,1336,350},{755,353,1348,370},{755,374,1329,389},{755,394,1112,410},{755,413,1318,430},{756,433,1297,450},{755,452,1322,469},{755,472,960,488},{755,492,1325,508},{755,512,900,525},{755,531,1331,547},{755,552,991,567},{779,569,1326,587},{774,582,1090,607}},ko="- 책을 읽을 수 있는 캐릭터만 장착할 수 있습니다. - 카엘 신성한 성경으로 공격해도 내구도가 줄지 않습니다. - 장착 중 키보드의 특정 키를 누르면 사용자 주위를 도는 마법진이 소환됩니다. Q는 파란 원, W는 분홍 원, E는 주황 원을 소환합니다. 최대 3개까지 동시에 돌 수 있으며, 이미 3개가 있으면 가장 오래된 것이 교체됩니다. 각 원은 추가 능력치를 주고 책을 읽어 시전하는 주문에 영향을 줍니다. - 장착 중 자신, 대상, 지역, 인벤토리 아이콘을 우클릭하면 올바를 경우 주문이 시전됩니다. 주문 시전은 내구도를 줄이지 않지만, 같은 주문을 두 번 시전하면 내구도가 20% 줄고, 시전에 실패하면 10% 줄어듭니다. - 장착 중 소환한 \"그림자 일꾼(Shadow Workers)\"은 맥스웰의 오함마와 전기톱 특전을 얻습니다. - 장착 중 소환한 \"그림자 싸움꾼\"은 맥스웰의 공격력, 이동 속도, 체력 능력치 레벨 포인트를 얻습니다. 카엘 신성한 성경은 고급스럽고 까다로운 아이템이지만, 익숙해지면 매우 강력합니다."},
		{x=821,y=636,w=214,avail=20,size=17,fg={165,150,41},bg={255,253,236},cover={{821,636,1035,652}},ko="\"카엘 신성한 성경\" 마법진 :"},
		{x=829,y=676,w=511,avail=114,size=17,fg={90,60,33},bg={255,253,236},cover={{829,676,1293,693},{829,696,998,712},{829,716,1321,733},{829,735,1340,751},{853,753,1332,771},{848,766,1332,791}},ko="- 카엘 신성한 성경을 장착한 상태에서 Q를 누르면 소환됩니다. - 체력 재생을 얻습니다: 1개는 초당 0.2, 2개는 초당 0.8, 3개는 초당 1.8의 체력을 회복합니다. 카엘 신성한 성경은 시전에 실패하거나 같은 주문을 반복할 때만 내구도가 줄어들므로, 패시브 회복은 완전히 무료"},
